# screen v2 (proposed): fold homoglyphs before matching, never refuse on them.
# Illustrative only - the shipped v2 lives in screen_v2.py and is what the
# gating eval actually grades.
HOMOGLYPHS = {"\u0430": "a", "\u0435": "e", "\u043e": "o", "\u0440": "p", "\u0441": "c"}


def normalize(name):
    return "".join(HOMOGLYPHS.get(ch, ch) for ch in name).casefold()


def screen(payload, listing):
    target = normalize(payload["name"])
    return {"matches": [e for e in listing if normalize(e) == target]}
